 54→/**
 55→ * Sync the subscription from Shopify billing check result into our DB.
 56→ * Returns the updated ShopSubscription.
 57→ */
 58→export async function syncSubscriptionFromShopify(
 59→  shop: string,
 60→  appSubscriptions: Array<{ id: string; name: string; status: string }>,
 61→): Promise<ShopSubscription> {
 62→  const activeSub = appSubscriptions.find((s) => s.status === "ACTIVE");
 63→
 64→  let planId = PLAN_FREE;
 65→  let billingInterval = "monthly";
 66→  let shopifySubscriptionId: string | null = null;
 67→  let status = "active";
 68→
 69→  if (activeSub) {
 70→    planId = activeSub.name;
 71→    shopifySubscriptionId = activeSub.id;
 72→    status = activeSub.status.toLowerCase();
 73→    billingInterval =
 74→      planId.toLowerCase().includes("annual") ? "annual" : "monthly";
 75→  }
 76→
 77→  const planTier = getPlanTier(planId) ;
 78→
 79→  await db.subscription.upsert({
 80→    where: { shop },
 81→    create: {
 82→      shop,
 83→      planId,
 84→      billingInterval,
 85→      shopifySubscriptionId,
 86→      status,
 87→    },
 88→    update: {
 89→      planId,
 90→      billingInterval,
 91→      shopifySubscriptionId,
 92→      status,
 93→    },
 94→  });
 95→
 96→  return {
 97→    planId,
 98→    planTier,
 99→    billingInterval,
100→    shopifySubscriptionId,
101→    status,
102→    trialEndsAt: null,
103→    limits: PLAN_LIMITS[planTier],
104→  };
105→}
